#include "heartRate.h"

int16_t IR_AC_Max = 20;
int16_t IR_AC_Min = -20;

int16_t IR_AC_Signal_Current = 0;
int16_t IR_AC_Signal_Previous;
int16_t IR_AC_Signal_min = 0;
int16_t IR_AC_Signal_max = 0;
int16_t IR_Average_Estimated;

int16_t positiveEdge = 0;
int16_t negativeEdge = 0;
int32_t ir_avg_reg = 0;

int16_t cbuf[32];
uint8_t offset = 0;

static const uint16_t FIRCoeffs[12] = {172, 321, 579, 927, 1360, 1858, 2390, 2916, 3391, 3768, 4012, 4096};

//  Heart Rate Monitor functions takes a sample value and the sample number
//  Returns true if a beat is detected
//  A running average of four samples is recommended for display on the screen.
bool checkForBeat(int32_t sample)
{
  bool beatDetected = false;

  //  Save current state
  IR_AC_Signal_Previous = IR_AC_Signal_Current;
  
  //This is good to view for debugging
  //Serial.print("Signal_Current: ");
  //Serial.println(IR_AC_Signal_Current);

  //  Process next data sample
  IR_Average_Estimated = averageDCEstimator(&ir_avg_reg, sample);
  IR_AC_Signal_Current = lowPassFIRFilter(sample - IR_Average_Estimated);

  //  Detect positive zero crossing (rising edge)
  if ((IR_AC_Signal_Previous < 0) & (IR_AC_Signal_Current >= 0))
  {
  
    IR_AC_Max = IR_AC_Signal_max; //Adjust our AC max and min
    IR_AC_Min = IR_AC_Signal_min;

    positiveEdge = 1;
    negativeEdge = 0;
    IR_AC_Signal_max = 0;

    //if ((IR_AC_Max - IR_AC_Min) > 100 & (IR_AC_Max - IR_AC_Min) < 1000)
    if ((IR_AC_Max - IR_AC_Min) > 20 & (IR_AC_Max - IR_AC_Min) < 1000)
    {
      //Heart beat!!!
      beatDetected = true;
    }
  }

  //  Detect negative zero crossing (falling edge)
  if ((IR_AC_Signal_Previous > 0) & (IR_AC_Signal_Current <= 0))
  {
    positiveEdge = 0;
    negativeEdge = 1;
    IR_AC_Signal_min = 0;
  }

  //  Find Maximum value in positive cycle
  if (positiveEdge & (IR_AC_Signal_Current > IR_AC_Signal_Previous))
  {
    IR_AC_Signal_max = IR_AC_Signal_Current;
  }

  //  Find Minimum value in negative cycle
  if (negativeEdge & (IR_AC_Signal_Current < IR_AC_Signal_Previous))
  {
    IR_AC_Signal_min = IR_AC_Signal_Current;
  }
  
  return(beatDetected);
}

//  Average DC Estimator
int16_t averageDCEstimator(int32_t *p, uint16_t x)
{
  *p += ((((long) x << 15) - *p) >> 4);
  return (*p >> 15);
}

//  Low Pass FIR Filter
int16_t lowPassFIRFilter(int16_t din)
{  
  cbuf[offset] = din;

  int32_t z = mul16(FIRCoeffs[11], cbuf[(offset - 11) & 0x1F]);
  
  for (uint8_t i = 0 ; i < 11 ; i++)
  {
    z += mul16(FIRCoeffs[i], cbuf[(offset - i) & 0x1F] + cbuf[(offset - 22 + i) & 0x1F]);
  }

  offset++;
  offset %= 32; //Wrap condition

  return(z >> 15);
}

//  Integer multiplier
int32_t mul16(int16_t x, int16_t y)
{
  return((long)x * (long)y);
}

/*
 * Mixly 4 MAX30102 state wrapper.
 * The bundled SparkFun driver and Maxim PBA beat detector retain their
 * original license notices in MAX30105.* and heartRate.*.
 */
#pragma once

#include <Arduino.h>
#include <Wire.h>
#include "MAX30105.h"
#include "heartRate.h"

class MixlyMAX30102HeartRate {
 public:
  MixlyMAX30102HeartRate();

  bool begin(uint8_t address = MAX30105_ADDRESS, uint32_t speed = I2C_SPEED_FAST);
  void configure(uint8_t powerLevel = 31, uint8_t sampleAverage = 4,
                 uint16_t sampleRate = 100, uint16_t pulseWidth = 411,
                 uint16_t adcRange = 4096);
  void update();
  void resetRate();

  bool ready() const;
  uint32_t ir() const;
  uint32_t red() const;
  bool beatDetected() const;
  float bpm() const;
  uint16_t averageBpm() const;
  bool fingerPresent(uint32_t threshold = 50000UL) const;
  void setRedLed(uint8_t amplitude);
  void setIrLed(uint8_t amplitude);
  float temperatureC();

 private:
  static const uint8_t RATE_SIZE = 4;
  MAX30105 sensor_;
  bool ready_;
  bool beat_;
  uint32_t ir_;
  uint32_t red_;
  uint32_t lastBeatMs_;
  float bpm_;
  uint16_t averageBpm_;
  uint8_t rates_[RATE_SIZE];
  uint8_t rateIndex_;
  uint8_t rateCount_;

  void processSample(uint32_t irValue, uint32_t redValue);
};

// Mixly 4 AVR's browser compiler mounts sketch .cpp files but only compiles
// the main sketch translation unit. The macro is emitted only by this plugin;
// a normal Arduino library build continues compiling the .cpp files normally.
#ifdef MIXLY_WASM_SINGLE_TRANSLATION_UNIT
#include "MAX30105.cpp"
#include "heartRate.cpp"
#include "MixlyMAX30102HeartRate.cpp"
#endif

#include "MixlyMAX30102HeartRate.h"

MixlyMAX30102HeartRate::MixlyMAX30102HeartRate()
    : ready_(false), beat_(false), ir_(0), red_(0), lastBeatMs_(0),
      bpm_(0.0f), averageBpm_(0), rateIndex_(0), rateCount_(0) {
  for (uint8_t i = 0; i < RATE_SIZE; ++i) rates_[i] = 0;
}

bool MixlyMAX30102HeartRate::begin(uint8_t address, uint32_t speed) {
  ready_ = sensor_.begin(Wire, speed, address);
  resetRate();
  return ready_;
}

void MixlyMAX30102HeartRate::configure(uint8_t powerLevel, uint8_t sampleAverage,
                                       uint16_t sampleRate, uint16_t pulseWidth,
                                       uint16_t adcRange) {
  if (!ready_) return;
  sensor_.setup(powerLevel, sampleAverage, 2, sampleRate, pulseWidth, adcRange);
  sensor_.setPulseAmplitudeGreen(0);
}

void MixlyMAX30102HeartRate::update() {
  beat_ = false;
  if (!ready_) return;
  sensor_.check();
  while (sensor_.available()) {
    const uint32_t irValue = sensor_.getFIFOIR();
    const uint32_t redValue = sensor_.getFIFORed();
    sensor_.nextSample();
    processSample(irValue, redValue);
  }
}

void MixlyMAX30102HeartRate::processSample(uint32_t irValue, uint32_t redValue) {
  ir_ = irValue;
  red_ = redValue;
  if (!checkForBeat((int32_t)irValue)) return;

  beat_ = true;
  const uint32_t now = millis();
  if (lastBeatMs_ != 0) {
    const uint32_t delta = now - lastBeatMs_;
    if (delta > 0) {
      const float nextBpm = 60000.0f / (float)delta;
      if (nextBpm > 20.0f && nextBpm < 255.0f) {
        bpm_ = nextBpm;
        rates_[rateIndex_] = (uint8_t)(nextBpm + 0.5f);
        rateIndex_ = (rateIndex_ + 1) % RATE_SIZE;
        if (rateCount_ < RATE_SIZE) ++rateCount_;
        uint16_t total = 0;
        for (uint8_t i = 0; i < rateCount_; ++i) total += rates_[i];
        averageBpm_ = rateCount_ ? total / rateCount_ : 0;
      }
    }
  }
  lastBeatMs_ = now;
}

void MixlyMAX30102HeartRate::resetRate() {
  beat_ = false;
  ir_ = 0;
  red_ = 0;
  lastBeatMs_ = 0;
  bpm_ = 0.0f;
  averageBpm_ = 0;
  rateIndex_ = 0;
  rateCount_ = 0;
  for (uint8_t i = 0; i < RATE_SIZE; ++i) rates_[i] = 0;
}

bool MixlyMAX30102HeartRate::ready() const { return ready_; }
uint32_t MixlyMAX30102HeartRate::ir() const { return ir_; }
uint32_t MixlyMAX30102HeartRate::red() const { return red_; }
bool MixlyMAX30102HeartRate::beatDetected() const { return beat_; }
float MixlyMAX30102HeartRate::bpm() const { return bpm_; }
uint16_t MixlyMAX30102HeartRate::averageBpm() const { return averageBpm_; }

bool MixlyMAX30102HeartRate::fingerPresent(uint32_t threshold) const {
  return ir_ >= threshold;
}

void MixlyMAX30102HeartRate::setRedLed(uint8_t amplitude) {
  if (ready_) sensor_.setPulseAmplitudeRed(amplitude);
}

void MixlyMAX30102HeartRate::setIrLed(uint8_t amplitude) {
  if (ready_) sensor_.setPulseAmplitudeIR(amplitude);
}

float MixlyMAX30102HeartRate::temperatureC() {
  return ready_ ? sensor_.readTemperature() : NAN;
}

